INSERT OR IGNORE INTO services(id,slug,data,published) VALUES('veb-sayt','veb-sayt','{"slug":"veb-sayt","number":"01","name":"Veb-sayt","short":"Landing, vizitka sayt yoki internet-do‘kon — telefon va kompyuterda birdek qulay.","description":"Biznesingizni internetda tanishtiradigan tez va tushunarli sayt. Matn tuzilishi, dizayn, dasturlash va domenga ulashgacha o‘zimiz bajaramiz.","features":["Telefon va kompyuterga moslashgan dizayn","Murojaat formasi va Telegram’ga xabar","Domen va hostingga ulash"],"icon":"web","price":"1 200 000 so‘mdan","term":"2 haftadan","packages":[{"name":"Landing","price":"1 200 000 so‘mdan","term":"2 haftadan","features":["Bitta sahifa","Telefon va kompyuterga moslashgan dizayn","Murojaat formasi va Telegram’ga xabar","Domen va hostingga ulash"],"recommended":false},{"name":"Vizitka sayt","price":"2 400 000 so‘mdan","term":"2 haftadan","features":["5 sahifagacha","Telefon va kompyuterga moslashgan dizayn","Murojaat formasi va Telegram’ga xabar","Domen va hostingga ulash","Matnni admin paneldan o‘zgartirish"],"recommended":true},{"name":"Internet-do‘kon","price":"","term":"","features":["Mahsulotlar katalogi va savat","Telefon va kompyuterga moslashgan dizayn","Murojaat formasi va Telegram’ga xabar","Domen va hostingga ulash","Matnni admin paneldan o‘zgartirish","Buyurtmalarni boshqarish"],"recommended":false}]}',1);
INSERT OR IGNORE INTO services(id,slug,data,published) VALUES('dizayn','dizayn','{"slug":"dizayn","number":"02","name":"Dizayn","short":"Yangi sayt yoki ilova uchun dizayn va mavjud saytni qayta dizayn qilish.","description":"Foydalanuvchi nimani, qayerda bosishini o‘ylab chiqamiz va buni toza, zamonaviy ko‘rinishga keltiramiz. Natija — dasturchiga tayyor Figma maketlari.","features":["Figma maketlari","Telefon va kompyuter ko‘rinishi","Ranglar va shriftlar tizimi"],"icon":"design","price":"","term":"","packages":[{"name":"Sayt dizayni","price":"","term":"","features":["Figma maketlari","Telefon va kompyuter ko‘rinishi","Ranglar va shriftlar tizimi"],"recommended":false},{"name":"Qayta dizayn (UI/UX)","price":"","term":"","features":["Figma maketlari","Telefon va kompyuter ko‘rinishi","Ranglar va shriftlar tizimi","Mavjud saytni tahlil qilish","Foydalanish qulayligini yaxshilash"],"recommended":false}]}',1);
INSERT OR IGNORE INTO services(id,slug,data,published) VALUES('telegram-bot','telegram-bot','{"slug":"telegram-bot","number":"03","name":"Telegram bot","short":"Buyurtma va mijozlar bilan ishlaydigan bot yoki Telegram ichidagi ilova (Mini App).","description":"Mijozlaringiz allaqachon Telegram’da. Buyurtma qabul qiladigan, savollarga javob beradigan va sizga xabar yuboradigan bot yasaymiz. Kattaroq vazifa uchun — Telegram ichida ochiladigan to‘liq ilova (Mini App).","features":["Menyu va tugmalar","Buyurtma yoki ariza qabul qilish","Admin uchun xabarnomalar"],"icon":"telegram","price":"1 200 000 so‘mdan","term":"1 haftadan","packages":[{"name":"Telegram bot","price":"1 200 000 so‘mdan","term":"1 haftadan","features":["Menyu va tugmalar","Buyurtma yoki ariza qabul qilish","Admin uchun xabarnomalar","Serverga o‘rnatish"],"recommended":true},{"name":"Mini App","price":"","term":"1,5 haftadan","features":["Menyu va tugmalar","Buyurtma yoki ariza qabul qilish","Admin uchun xabarnomalar","Serverga o‘rnatish","Telegram ichida ochiladigan ilova oynasi","Admin panel"],"recommended":false}]}',1);
INSERT OR IGNORE INTO services(id,slug,data,published) VALUES('ilova','ilova','{"slug":"ilova","number":"04","name":"Ilova","short":"Veb-ilova, CRM yoki mobil ilova — ishingizni avtomatlashtiradigan dastur.","description":"Jadval va qog‘ozda yuritilayotgan ishni bitta dasturga jamlaymiz: mijozlar, buyurtmalar, hisobotlar. Kerak bo‘lsa, telefon uchun ilova ham yasaymiz.","features":["Foydalanuvchilar va ruxsatlar","Ma’lumotlar bazasi","Hisobotlar"],"icon":"app","price":"3 600 000 so‘mdan","term":"","packages":[{"name":"Veb-ilova (CRM)","price":"3 600 000 so‘mdan","term":"","features":["Foydalanuvchilar va ruxsatlar","Ma’lumotlar bazasi","Hisobotlar","Brauzerda ishlaydi"],"recommended":true},{"name":"Mobil ilova","price":"","term":"","features":["Foydalanuvchilar va ruxsatlar","Ma’lumotlar bazasi","Hisobotlar","Android va iOS uchun"],"recommended":false}]}',1);
INSERT OR IGNORE INTO projects(id,slug,data,published) VALUES('dalolat-site','dalolat-sayti','{"id":"dalolat-site","slug":"dalolat-sayti","name":"dalolat.app","category":"Saytlar","status":"Ishlayapti","summary":"DALOLAT ilovasining besh tilli taqdimot sayti.","description":"DALOLAT ilovasi uchun alohida sayt: ilova imkoniyatlari, savol-javob va brauzerda Telegram orqali kirish. Besh tilda ishlaydi.","purpose":"Ilovani Telegram’dan tashqarida ham tanishtirish va foydalanuvchini to‘g‘ridan-to‘g‘ri ilovaga olib kirish.","features":["5 til: o‘zbek, rus, ingliz, turk, arab","Brauzerda Telegram orqali kirish","Telefon va kompyuterga moslashgan"],"platforms":["Veb-sayt"],"cover":"dalolat","url":"https://dalolat.app","published":true}',1);
INSERT OR IGNORE INTO projects(id,slug,data,published) VALUES('sado-site','sado-sayti','{"id":"sado-site","slug":"sado-sayti","name":"sado.alifbit.org","category":"Saytlar","status":"Ishlayapti","summary":"Sado dasturining sayti: yuklab olish, tariflar va kalit so‘rash.","description":"Sado uchun mahsulot sayti: dastur qanday ishlashi, tariflar, Windows uchun yuklab olish va kalit so‘rash formasi.","purpose":"Dasturni tanishtirish va foydalanuvchini yuklab olishgacha olib borish.","features":["Windows uchun yuklab olish","Tariflar paneli","Kalit so‘rash formasi"],"platforms":["Veb-sayt"],"cover":"voice","url":"https://sado.alifbit.org","published":true}',1);
INSERT OR IGNORE INTO courses(id,slug,data,published) VALUES('vayb-koding','vayb-koding','{"id":"vayb-koding","slug":"vayb-koding","title":"Vayb koding","tagline":"Kod yozishni bilmasangiz ham, AI bilan sayt va Telegram bot yasang.","description":"Kursda AI yordamchiga vazifani to‘g‘ri tushuntirishni, u yozgan kodni tekshirishni va tayyor loyihani internetga chiqarishni o‘rganasiz. Har bir darsda haqiqiy loyiha ustida ishlaysiz.","price":"1 200 000 so‘m","format":"Onlayn","start":"","steps":[{"title":"Reja tuzish","text":"G‘oyani AI tushunadigan aniq topshiriqqa aylantirasiz."},{"title":"AI bilan yozish","text":"AI yordamchi kod yozadi, siz har qadamni tekshirib borasiz."},{"title":"Ishga tushirish","text":"Tayyor loyihani internetga chiqarasiz va boshqalarga ulashasiz."}],"contents":["AI yordamchini sozlash","G‘oyani topshiriqqa aylantirish","Sayt yasash","Telegram bot yasash","Xatolarni tuzatish","Internetga chiqarish"],"published":false}',0);
-- «Saytlar» kategoriyasi mavjud ro'yxat oxiriga qo'shiladi; admin qo'shgan kategoriyalar saqlanadi.
UPDATE settings SET data=json_insert(data,'$[#]','Saytlar') WHERE key='categories' AND NOT EXISTS (SELECT 1 FROM json_each(settings.data) WHERE value='Saytlar');
